def tags(items):return '<div class="tags">'+''.join(f'<span class="tag">{e(x)}</span>' for x in items)+'</div>'
def para(s):return f'<p>{s}</p>'
def bullets(items):return '<ul>'+''.join(f'<li>{x}</li>' for x in items)+'</ul>'
def metrics(items):return '<div class="metrics">'+''.join(f'<div class="metric"><strong>{e(v)}</strong><span>{e(k)}</span></div>' for v,k in items)+'</div>'
def table(headers,rows):return '<table class="mini-table"><thead><tr>'+''.join(f'<th scope="col">{e(x)}</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td>{e(str(x))}</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table>'
def figure(src,caption,cover=False):return f'<figure class="{"cover-figure" if cover else "figure"}"><button type="button" class="image-button" aria-label="Enlarge figure: {e(caption,quote=True)}"><img src="assets/{src}" alt="{e(caption,quote=True)}" loading="{"eager" if cover else "lazy"}" width="1600" height="900" style="height:auto"></button><figcaption>{caption}</figcaption></figure>'

