def header(home=False):
 prefix='' if home else 'index.html'
 return f'''<a class="skip" href="#main">Skip to content</a><header class="site-header"><div class="wrap nav"><a class="brand" href="index.html"><span class="brand-mark" aria-hidden="true">ZT</span>Zihao Tan<span style="color:var(--orange)">.</span></a><nav aria-label="Main navigation"><a href="{prefix}#work">Projects</a><a href="{prefix}#about">About</a><a href="{prefix}#games">Games</a><a class="contact-link" href="mailto:ht1123@ic.ac.uk">Get in touch</a></nav></div></header>'''
def footer():return '<div class="wrap footer"><span>© 2026 Zihao Tan</span><span>Research · engineering · independent games</span><a href="#top">Back to top ↑</a></div>'
def document(title,description,body,home=False):return f'''<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{e(title)} | Zihao Tan</title><meta name="description" content="{e(description,quote=True)}"><meta name="theme-color" content="#183c38"><link rel="icon" href="assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="style.css"><script src="app.js" defer></script></head><body id="top">{header(home)}{body}{footer()}<dialog id="figure-dialog" class="lightbox" aria-label="Expanded project figure"><button type="button" class="lightbox-close" aria-label="Close expanded figure">×</button><img src="assets/favicon.svg" alt=""><p class="lightbox-caption"></p></dialog></body></html>'''
def card(p):
 media=XR_SVG if not p['thumb'] else f'<img src="assets/{p["thumb"]}" alt="{e(p["title"],quote=True)} — {"Unitree Robotics reference image" if p["slug"]=="xr-teleoperation" else "project figure"}" loading="lazy" width="900" height="560">'
 cls='xr' if not p['thumb'] else ('lab' if p['slug']=='impedimetric-respiration' else 'software' if p['slug']=='patient-monitoring' else '')
 if p['slug']=='xr-teleoperation':
  media='<video data-autoplay autoplay muted loop playsinline preload="metadata" poster="media/unitree-early-configuration-poster.jpg" aria-label="Early-stage Unitree robot configuration preview" width="1172" height="916"><source src="media/unitree-early-configuration.mp4" type="video/mp4"></video>'
  cls='xr xr-video-preview'
 credit='<span class="media-credit">Early-stage robot configuration</span>' if p['slug']=='xr-teleoperation' else ''
 return f'''<a class="project-card" href="{p['slug']}.html" data-category="{p['category']}"><div class="project-media {cls}"><span class="project-label">{p['kind']}</span>{media}{credit}</div><div class="card-meta"><span>{p['number']} / {p['role']}</span><span>{p['year']}</span></div><div class="card-title"><h3>{p['title']}</h3></div><p>{p['short']}</p>{tags(p['stack'][:3])}</a>'''

def game_video(slug,label,process=False):
 return f'''<div class="{'making-media' if process else 'game-player'}"><video data-autoplay autoplay muted loop playsinline controls preload="none" poster="media/{slug}-poster.jpg" aria-label="{e(label,quote=True)}"><source data-src="media/{slug}.mp4" type="video/mp4">Your browser does not support embedded video.</video></div>'''
def game_photo(slug,caption):
 return f'''<figure class="making-figure"><button type="button" class="image-button making-media" aria-label="Enlarge image: {e(caption,quote=True)}"><img src="media/{slug}.webp" alt="{e(caption,quote=True)}" loading="lazy" width="1400" height="1050"></button><figcaption>{caption}</figcaption></figure>'''
games_html=f'''<section id="games" class="games"><div class="wrap"><div class="section-head"><div><div class="eyebrow">03 / Beyond the lab</div><h2>I also build worlds.</h2></div><p>I’ve been making Unity games since 2023. All three games below are solo projects, developed by me.</p></div><div class="game-section-toolbar"><p>From learning C# to drawing characters, building game systems and bringing them into the physical world.</p><button type="button" class="video-toggle" aria-pressed="false">Pause all videos</button></div>
<article class="game-showcase" id="capyria"><div class="game-intro"><div class="eyebrow">01 / My first complete game</div><h3>Capyria</h3><div class="game-genre">Roguelike side-scroller · Unity & C#</div><p>My first complete game. I hand-coded most of the systems and painted all of the assets myself, learning C# from scratch along the way.</p><p>Players collect weapons and equipment, take on bosses and combine different rune effects to gain special abilities.</p></div>{game_video('capyria','Capyria gameplay trailer')}<div class="game-learning"><span class="eyebrow">What I learned</span><p>C# from scratch, A* pathfinding and other gameplay algorithms—and how to bring code, art and mechanics together into a complete game.</p></div></article>
<article class="game-showcase" id="yokai"><div class="game-intro"><div class="eyebrow">02 / From game art to physical characters</div><h3>Yokai</h3><div class="game-genre">Japanese-inspired boss rush · Unity & Blender</div><p>A boss-rush game where players fight Japanese-inspired yokai. This project reflects a big step forward in my skills, with characters I designed for the game.</p><p>I also took those characters beyond the screen: modelling them in Blender, printing them with a Bambu Lab A1 and painting the finished figures myself.</p></div>{game_video('yokai','Yokai boss-rush gameplay')}<div class="game-learning"><span class="eyebrow">What I learned</span><p>Blender modelling, preparing models for 3D printing, printing techniques and painting physical character models.</p></div><div class="making-section"><div class="making-heading"><h4>From screen to shelf.</h4><p>Character design, printing and painting—all part of the same solo project.</p></div><div class="making-grid">{game_photo('yokai-painted-model','A painted Yokai character model alongside its in-game design.')}{game_photo('yokai-painting-process','Preparing to paint the printed character models.')}<figure class="making-figure">{game_video('yokai-printing','Yokai character being printed on a Bambu Lab A1',True)}<figcaption>Printing a character model with the Bambu Lab A1.</figcaption></figure><figure class="making-figure">{game_video('yokai-printed-model','A printed Yokai character held beside its in-game design',True)}<figcaption>A printed character before painting, shown with the game.</figcaption></figure></div></div></article>
<article class="game-showcase" id="protocol-neon"><div class="game-intro"><div class="eyebrow">03 / Current game development</div><h3>Protocol Neon</h3><div class="game-genre">Cyberpunk farming · Unity & Spine</div><p>A farming game set in a stylised cyberpunk world.</p><p>My latest solo project is also an opportunity to develop my character-animation workflow, from setting up a skeleton to bringing it to life.</p></div>{game_video('protocol-neon','Protocol Neon cyberpunk farming gameplay')}<div class="game-learning"><span class="eyebrow">What I learned</span><p>Spine animation, building bone rigs and using skeletal animation to bring 2D characters to life. I also learned to build local multiplayer using FishNet.</p></div></article></div></section>'''

home=f'''<main id="main"><section class="hero wrap"><div class="hero-grid"><div><div class="eyebrow"><span class="dot"></span> Biomedical engineering · Imperial College London</div><h1>Decoding neural signals.<br>Building interactive systems.</h1><p class="hero-copy">I’m Zihao, an MEng Biomedical Engineering student exploring neural decoding, intelligent systems and the ways people interact with technology.</p><div class="hero-actions"><a class="button" href="#work">Explore my projects <span>↓</span></a><a class="button games-jump" href="#games">My Unity games <span aria-hidden="true">↓</span></a><a class="button secondary" href="#about">A little about me</a></div></div></div><div class="intro-strip"><span>MY WORK, IN A FEW DIRECTIONS</span><strong>Neural decoding</strong><strong>Biomedical systems</strong><strong>XR & robotics</strong><strong>Interactive worlds</strong></div></section>
<section id="work" class="section wrap"><div class="section-head"><div><div class="eyebrow">01 / Selected projects</div><h2>Questions, prototypes<br>and things I’ve built.</h2></div><p>From decoding neural activity to building biomedical tools. Each project opens into its methods, figures and findings.</p></div><div class="filters" role="group" aria-label="Filter projects"><button class="filter" data-filter="all" aria-pressed="true">All projects <span aria-hidden="true">06</span></button><button class="filter" data-filter="research" aria-pressed="false">Neuroscience & ML</button><button class="filter" data-filter="engineering" aria-pressed="false">Engineering</button><button class="filter" data-filter="robotics" aria-pressed="false">XR & robotics</button></div><p id="filter-status" class="sr-only" aria-live="polite">Showing 6 projects</p><div class="project-grid">{''.join(card(p) for p in projects)}</div></section>
<section id="about" class="wrap about"><div><div class="eyebrow">02 / About me</div><h2>Curious about the<br>human side of engineering.</h2><a class="about-next" href="#games"><span class="eyebrow">Keep exploring</span><span class="about-next-title">Three solo games.<br>Built since 2023.</span><span class="about-preview-grid"><span><img src="media/capyria-poster.jpg" alt="Capyria gameplay preview" loading="lazy" width="1280" height="720"><span>Capyria</span></span><span><img src="media/yokai-poster.jpg" alt="Yokai gameplay preview" loading="lazy" width="1280" height="718"><span>Yokai</span></span><span><img src="media/protocol-neon-poster.jpg" alt="Protocol Neon gameplay preview" loading="lazy" width="1274" height="720"><span>Protocol Neon</span></span></span><span class="about-next-link">Watch the gameplay <span aria-hidden="true">↓</span></span></a></div><div><p>I’m studying for an MEng in Biomedical Engineering at Imperial College London, with expected graduation in 2027. My interests lie in brain–machine interfaces, computational neuroscience and adaptive machine learning.</p><p>I enjoy following a problem across layers: understanding a biological signal, building a model, testing a system and designing the interface someone will actually use. Alongside my academic work, I develop independent games in Unity.</p><div class="skill-row"><strong>Code & models</strong><span>Python · PyTorch · MATLAB · JavaScript · C#</span></div><div class="skill-row"><strong>Systems & tools</strong><span>Unity · Isaac Sim · XR · SQL · Git · SPICE</span></div><div class="skill-row"><strong>Research focus</strong><span>Neural decoding · signal processing · adaptation</span></div></div></section>
{games_html}
<section id="contact" class="wrap contact"><div><div class="eyebrow">Let’s connect</div><h2>Feel free to ask me<br>anything.</h2><p>Research, engineering or something interactive—get in touch.</p></div><a class="button" href="mailto:ht1123@ic.ac.uk">ht1123@ic.ac.uk</a></section></main>'''
